const cells=new Map();
function colName(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function parseAddress(a){const m=/^([A-Z]+)([1-9]\d*)$/.exec(a);if(!m)return null;let c=0;for(const x of m[1])c=c*26+x.charCodeAt(0)-64;return {col:c-1,row:Number(m[2])-1}}
