function buildGrid(){ui.grid.innerHTML='';const corner=document.createElement('div');corner.className='corner';corner.style.gridArea='1 / 1';ui.grid.append(corner);for(let c=0;c<COLS;c++){const h=document.createElement('div');h.className='col-header';h.textContent=colName(c);h.style.gridArea=`1 / ${c+2}`;ui.grid.append(h)}for(let r=0;r<ROWS;r++){const h=document.createElement('div');h.className='row-header';h.textContent=r+1;h.style.gridArea=`${r+2} / 1`;ui.grid.append(h);for(let c=0;c<COLS;c++){const a=address(r,c),el=document.createElement('div');el.className='cell';el.dataset.address=a;el.setAttribute('role','gridcell');el.setAttribute('tabindex','-1');el.style.gridArea=`${r+2} / ${c+2}`;cells.set(a,el);ui.grid.append(el)}}render()}
function render(){if(!state.workbook)return;for(const [a,el] of cells){el.textContent=displayValue(a);el.title=raw(a);el.classList.toggle('invalid',!!formulaError(a));el.classList.toggle('conflict',state.conflicts.has(a));el.classList.remove('selected','primary','formula-ref')}eachRange(a=>cells.get(a)?.classList.add('selected'));cells.get(state.selection.end)?.classList.add('primary');for(const a of state.formulaRefs)cells.get(a)?.classList.add('formula-ref');renderRemote();ui.name.value=rangeAddress();ui.formula.value=raw(state.selection.end);const err=formulaError(state.selection.end);$('formula-error').textContent=err?`Formula: ${err}`:'';$('undo').disabled=!state.undo.length;$('redo').disabled=!state.redo.length;$('fill-down').disabled=bounds().r1===bounds().r2;$('fill-right').disabled=bounds().c1===bounds().c2;updateStatus()}
