function updateFormulaHelpers(input){closeFunctionList();state.formulaRefs=[];const value=input.value;if(value.startsWith('=')){const matches=value.toUpperCase().match(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?/g)||[];for(const m of matches){const [s,e=s]=m.split(':');eachRange(a=>state.formulaRefs.push(a),{start:s,end:e})}const prefix=/([A-Za-z]+)$/.exec(value.slice(0,input.selectionStart));if(prefix){const options=FUNCTIONS.filter(x=>x.startsWith(prefix[1].toUpperCase()));if(options.length)showFunctions(input,options,prefix[1])}}render()}
