function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

class FormulaError extends Error{}
function tokenize(text){const out=[];let i=0;while(i<text.length){const rest=text.slice(i),space=/^\s+/.exec(rest);if(space){i+=space[0].length;continue}const m=/^(\d+(?:\.\d+)?|[A-Za-z]+[1-9]\d*|[A-Za-z]+|[()+\-*/, :])/.exec(rest);if(!m)throw new FormulaError('Invalid formula');const value=m[1];if(value!==' ')out.push(value);i+=value.length}return out}
function evaluate(addressValue,cellsData=sheet().cells,stack=[]){const value=cellsData[addressValue]??'';if(!value.startsWith('='))return value;if(stack.includes(addressValue))throw new FormulaError('Circular reference');const tokens=tokenize(value.slice(1));let i=0;
  const numeric=v=>{if(v instanceof FormulaError)throw v;const n=Number(v);return Number.isFinite(n)?n:0};
  const ref=a=>evaluate(a,cellsData,[...stack,addressValue]);
  function primary(){const t=tokens[i++];if(t===undefined)throw new FormulaError('Invalid formula');if(t==='('){const v=expression();if(tokens[i++]!==')')throw new FormulaError('Missing )');return v}if(t==='-')return -numeric(primary());if(/^\d/.test(t))return Number(t);if(/^[A-Za-z]+[1-9]/.test(t)){return ref(t.toUpperCase())}if(/^[A-Za-z]+$/.test(t)){const fn=t.toUpperCase();if(!FUNCTIONS.includes(fn)||tokens[i++]!=='(')throw new FormulaError(`Unknown function ${fn}`);const args=[];if(tokens[i]!==')'){while(true){const start=tokens[i];if(/^[A-Za-z]+[1-9]/.test(start||'')&&tokens[i+1]===':'){i+=2;const end=tokens[i++];if(!/^[A-Za-z]+[1-9]/.test(end||''))throw new FormulaError('Invalid range');const a=parseAddress(start.toUpperCase()),b=parseAddress(end.toUpperCase());for(let r=Math.min(a.row,b.row);r<=Math.max(a.row,b.row);r++)for(let c=Math.min(a.col,b.col);c<=Math.max(a.col,b.col);c++)args.push(numeric(ref(address(r,c))))}else args.push(numeric(expression()));if(tokens[i]===','){i++;continue}break}}if(tokens[i++]!==')')throw new FormulaError('Missing )');if(fn==='SUM')return args.reduce((a,b)=>a+b,0);if(fn==='AVG')return args.length?args.reduce((a,b)=>a+b,0)/args.length:0;if(fn==='MIN')return args.length?Math.min(...args):0;if(fn==='MAX')return args.length?Math.max(...args):0;return args.filter(Number.isFinite).length}throw new FormulaError('Invalid formula')}
  function term(){let v=primary();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],n=numeric(primary());if(op==='/'&&n===0)throw new FormulaError('Division by zero');v=op==='*'?numeric(v)*n:numeric(v)/n}return v}
  function expression(){let v=term();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],n=numeric(term());v=op==='+'?numeric(v)+n:numeric(v)-n}return v}
  const result=expression();if(i!==tokens.length)throw new FormulaError('Invalid formula');return result;
}
function displayValue(a){const value=raw(a);if(!value.startsWith('='))return value;try{const result=evaluate(a);return Number.isFinite(result)?String(Math.round((result+Number.EPSILON)*1e10)/1e10):String(result)}catch(e){return e.message.includes('Circular')?'#CIRC!':e.message.includes('zero')?'#DIV/0!':'#ERROR!'}}
function formulaError(a){if(!raw(a).startsWith('='))return '';try{evaluate(a);return ''}catch(e){return e.message}}

function buildGrid(){ui.grid.innerHTML='';const corner=document.createElement('div');corner.className='corner';corner.style.gridArea='1 / 1';ui.grid.append(corner);for(let c=0;c<COLS;c++){const h=document.createElement('div');h.className='col-header';h.textContent=colName(c);h.style.gridArea=`1 / ${c+2}`;ui.grid.append(h)}for(let r=0;r<ROWS;r++){const h=document.createElement('div');h.className='row-header';h.textContent=r+1;h.style.gridArea=`${r+2} / 1`;ui.grid.append(h);for(let c=0;c<COLS;c++){const a=address(r,c),el=document.createElement('div');el.className='cell';el.dataset.address=a;el.setAttribute('role','gridcell');el.setAttribute('tabindex','-1');el.style.gridArea=`${r+2} / ${c+2}`;cells.set(a,el);ui.grid.append(el)}}render()}
function render(){if(!state.workbook)return;for(const [a,el] of cells){el.textContent=displayValue(a);el.title=raw(a);el.classList.toggle('invalid',!!formulaError(a));el.classList.toggle('conflict',state.conflicts.has(a));el.classList.remove('selected','primary','formula-ref')}eachRange(a=>cells.get(a)?.classList.add('selected'));cells.get(state.selection.end)?.classList.add('primary');for(const a of state.formulaRefs)cells.get(a)?.classList.add('formula-ref');renderRemote();ui.name.value=rangeAddress();ui.formula.value=raw(state.selection.end);const err=formulaError(state.selection.end);$('formula-error').textContent=err?`Formula: ${err}`:'';$('undo').disabled=!state.undo.length;$('redo').disabled=!state.redo.length;$('fill-down').disabled=bounds().r1===bounds().r2;$('fill-right').disabled=bounds().c1===bounds().c2;updateStatus()}
function updateStatus(message){ui.revision.textContent=`Revision ${state.revision}`;ui.feedback.className='feedback '+(state.conflicts.size?'conflict':state.saving?'saving':state.dirty?'dirty':'saved');ui.feedback.textContent=message||(state.conflicts.size?`Conflict in ${[...state.conflicts].join(', ')}`:state.saving?'Saving…':state.dirty?'Unsaved changes':'Saved');$('save').disabled=state.saving||!state.dirty||!!state.preview}
function renderRemote(){ui.grid.querySelectorAll('.remote-outline').forEach(x=>x.remove());for(const p of state.presence.filter(p=>p.id!==state.sessionId)){const parts=p.selection.split(':'),b=bounds({start:parts[0],end:parts[1]||parts[0]});const box=document.createElement('div');box.className='remote-outline';box.style.setProperty('--color',p.color);box.style.left=`${44+b.c1*112}px`;box.style.top=`${30+b.r1*28}px`;box.style.width=`${(b.c2-b.c1+1)*112}px`;box.style.height=`${(b.r2-b.r1+1)*28}px`;box.title=`${p.name}: ${p.selection}`;ui.grid.append(box)}}
function renderPresence(){const count=new Map();for(const p of state.presence)count.set(p.name,(count.get(p.name)||0)+1);$('presence-summary').textContent=state.presence.length?`${state.presence.length} live view${state.presence.length===1?'':'s'} · ${[...count].map(([n,c])=>`${n} (${c})`).join(', ')}`:'Only you are here';ui.legend.innerHTML=state.presence.map(p=>`<span class="presence-chip" style="--color:${p.color}"><i class="presence-dot"></i>${escapeHtml(p.name)} · ${escapeHtml(p.selection)}</span>`).join('');renderRemote()}
function select(start,end=start,scroll=true){if(!parseAddress(start)||!parseAddress(end))return;state.selection={start,end};state.anchor=start;render();if(scroll)cells.get(end)?.scrollIntoView({block:'nearest',inline:'nearest'});sendPresence();loadCellHistory()}
let presenceTimer;function sendPresence(){clearTimeout(presenceTimer);if(!state.sessionId)return;presenceTimer=setTimeout(()=>fetch(`/api/sessions/${state.sessionId}/presence`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:state.user,selection:rangeAddress()})}).catch(()=>{}),80)}
function transact(changes){const actual=[];for(const [a,value] of changes){const old=raw(a),next=String(value);if(old!==next)actual.push([a,old,next])}if(!actual.length)return;for(const [a,,v] of actual)setRawDirect(a,v);state.undo.push(actual);state.redo=[];state.conflicts.clear();markDirty();render()}
function markDirty(){state.dirty=JSON.stringify(state.workbook)!==JSON.stringify(state.saved);updateStatus();clearTimeout(state.saveTimer);if(state.dirty&&!state.preview)state.saveTimer=setTimeout(save,1200)}
function undo(){const tx=state.undo.pop();if(!tx)return;for(const [a,old] of tx)setRawDirect(a,old);state.redo.push(tx);markDirty();render()}
function redo(){const tx=state.redo.pop();if(!tx)return;for(const [a,,value] of tx)setRawDirect(a,value);state.undo.push(tx);markDirty();render()}

function beginEdit(a=state.selection.end,initial=null){if(state.preview)return;endEdit(false);const cell=cells.get(a),pos=cell.getBoundingClientRect(),gridPos=ui.grid.getBoundingClientRect(),input=document.createElement('input');input.className='cell-editor';input.value=initial===null?raw(a):initial;input.style.left=`${pos.left-gridPos.left}px`;input.style.top=`${pos.top-gridPos.top}px`;input.style.width=`${Math.max(112,pos.width)}px`;ui.grid.append(input);state.editing={address:a,input};state.editOriginal=raw(a);ui.formula.value=input.value;input.focus();if(initial===null)input.select();else input.setSelectionRange(input.value.length,input.value.length);input.addEventListener('input',()=>{ui.formula.value=input.value;updateFormulaHelpers(input)});input.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key==='Tab'){e.preventDefault();const move=e.key==='Tab'?[0,e.shiftKey?-1:1]:[e.shiftKey?-1:1,0];endEdit(true);moveSelection(...move)}else if(e.key==='Escape'){e.preventDefault();endEdit(false)}});updateFormulaHelpers(input)}
function endEdit(commit=true){if(!state.editing)return;const {address:a,input}=state.editing,value=input.value;state.editing=null;input.remove();closeFunctionList();state.formulaRefs=[];if(commit&&value!==state.editOriginal)transact([[a,value]]);else render()}
function updateFormulaHelpers(input){closeFunctionList();state.formulaRefs=[];const value=input.value;if(value.startsWith('=')){const matches=value.toUpperCase().match(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?/g)||[];for(const m of matches){const [s,e=s]=m.split(':');eachRange(a=>state.formulaRefs.push(a),{start:s,end:e})}const prefix=/([A-Za-z]+)$/.exec(value.slice(0,input.selectionStart));if(prefix){const options=FUNCTIONS.filter(x=>x.startsWith(prefix[1].toUpperCase()));if(options.length)showFunctions(input,options,prefix[1])}}render()}
function showFunctions(input,options,prefix){const list=document.createElement('div');list.className='function-list';list.id='function-list';list.innerHTML=options.map(x=>`<div>${x}</div>`).join('');list.style.left=input.style.left;list.style.top=`${parseFloat(input.style.top)+28}px`;list.addEventListener('mousedown',e=>{const fn=e.target.textContent;if(!fn)return;e.preventDefault();const p=input.selectionStart;input.value=input.value.slice(0,p-prefix.length)+fn+'('+input.value.slice(p);input.focus();input.setSelectionRange(p-prefix.length+fn.length+1,p-prefix.length+fn.length+1);input.dispatchEvent(new Event('input'))});ui.grid.append(list)}
function closeFunctionList(){$('function-list')?.remove()}
function insertFormulaReference(ref){if(!state.editing||!state.editing.input.value.startsWith('='))return false;const input=state.editing.input,start=input.selectionStart,end=input.selectionEnd,text=input.value;const selected=text.slice(start,end);let left=start,right=end;if(/^[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?$/i.test(selected)){}else{const before=text.slice(0,start),m=/([A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?)$/i.exec(before);if(m&&!/[+\-*/,]\s*$/.test(before.slice(0,m.index))){left=m.index}else if(m&&!/[+\-*/,]\s*$/.test(before.slice(m.index+m[0].length))){left=m.index}}input.value=text.slice(0,left)+ref+text.slice(right);input.focus();input.setSelectionRange(left,left+ref.length);input.dispatchEvent(new Event('input'));return true}
function moveSelection(dr,dc,extend=false){const p=parseAddress(state.selection.end);const next=address(Math.max(0,Math.min(ROWS-1,p.row+dr)),Math.max(0,Math.min(COLS-1,p.col+dc)));if(extend){state.selection.end=next;render();sendPresence()}else select(next)}

function shiftFormula(value,dr,dc){return value.replace(/([A-Z]+)([1-9]\d*)/g,(_,col,row)=>{const p=parseAddress(col+row);return address(Math.max(0,p.row+dr),Math.max(0,p.col+dc))})}
function fill(direction){const b=bounds(),changes=[];if(direction==='down'){for(let c=b.c1;c<=b.c2;c++){const first=raw(address(b.r1,c)),second=b.r1<b.r2?raw(address(b.r1+1,c)):'';const numeric=first!==''&&second!==''&&Number.isFinite(Number(first))&&Number.isFinite(Number(second));const step=numeric?Number(second)-Number(first):0;for(let r=b.r1+1;r<=b.r2;r++){let v=numeric?String(Number(first)+step*(r-b.r1)):first.startsWith('=')?shiftFormula(first,r-b.r1,0):first;changes.push([address(r,c),v])}}}else{for(let r=b.r1;r<=b.r2;r++){const first=raw(address(r,b.c1)),second=b.c1<b.c2?raw(address(r,b.c1+1)):'';const numeric=first!==''&&second!==''&&Number.isFinite(Number(first))&&Number.isFinite(Number(second));const step=numeric?Number(second)-Number(first):0;for(let c=b.c1+1;c<=b.c2;c++){let v=numeric?String(Number(first)+step*(c-b.c1)):first.startsWith('=')?shiftFormula(first,0,c-b.c1):first;changes.push([address(r,c),v])}}}transact(changes)}
function parseClipboard(text){const rows=text.trimEnd().split(/\r?\n/);return rows.map(row=>row.includes('\t')?row.split('\t'):parseCsv(row))}
function parseCsv(row){const out=[];let cur='',quoted=false;for(let i=0;i<row.length;i++){const c=row[i];if(c==='"'&&row[i+1]==='"'){cur+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur=''}else cur+=c}out.push(cur);return out}
function copy(cut=false){const b=bounds(),rows=[];for(let r=b.r1;r<=b.r2;r++){const values=[];for(let c=b.c1;c<=b.c2;c++)values.push(raw(address(r,c)));rows.push(values.join('\t'))}navigator.clipboard?.writeText(rows.join('\n'));if(cut)transact((()=>{const a=[];eachRange(x=>a.push([x,'']));return a})())}
function paste(text){const matrix=parseClipboard(text),start=parseAddress(state.selection.start),changes=[];matrix.forEach((row,ri)=>row.forEach((v,ci)=>{if(start.row+ri<ROWS&&start.col+ci<COLS)changes.push([address(start.row+ri,start.col+ci),v])}));transact(changes);if(matrix.length)select(state.selection.start,address(Math.min(ROWS-1,start.row+matrix.length-1),Math.min(COLS-1,start.col+Math.max(...matrix.map(x=>x.length))-1)))}
function clearSelection(){const changes=[];eachRange(a=>changes.push([a,'']));transact(changes)}
function matches(){const q=$('find').value.toLowerCase();if(!q)return[];const out=[];for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){const a=address(r,c);if(raw(a).toLowerCase().includes(q))out.push(a)}return out}
function findNext(){const found=matches();if(!found.length){updateStatus('No matches');return null}const current=state.selection.end,index=found.indexOf(current),next=found[(index+1)%found.length];select(next);return next}
function replaceCurrent(){const q=$('find').value;if(!q)return;let a=state.selection.end;if(!raw(a).toLowerCase().includes(q.toLowerCase()))a=findNext();if(a)transact([[a,raw(a).replace(new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i'),$('replace').value)]])}
function replaceAll(){const q=$('find').value;if(!q)return;const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),changes=matches().map(a=>[a,raw(a).replace(re,$('replace').value)]);transact(changes);updateStatus(changes.length?`Replaced ${changes.length} cell${changes.length===1?'':'s'}`:'No matches')}

async function request(url,options){const res=await fetch(url,options);let data={};try{data=await res.json()}catch{}if(!res.ok)throw Object.assign(new Error(data.error||`Request failed (${res.status})`),{status:res.status,data});return data}
async function save(){if(state.saving||!state.dirty||state.preview)return;endEdit(true);clearTimeout(state.saveTimer);state.saving=true;updateStatus();try{const local=clone(state.workbook);const result=await request('/api/workbooks/ops-plan/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workbookId:'ops-plan',baseRevision:state.revision,workbook:local,sessionId:state.sessionId,userId:state.user})});state.revision=result.revision;state.workbook=result.workbook;state.saved=clone(result.workbook);state.dirty=false;state.conflicts.clear();state.saving=false;render();await Promise.all([loadRevisions(),loadCellHistory()])}catch(e){state.saving=false;if(e.status===409&&e.data.workbook){const local=clone(state.workbook),server=e.data.workbook;state.revision=e.data.currentRevision;state.saved=clone(server);state.workbook=clone(server);for(const conflict of e.data.conflicts){setRawDirect(conflict.address,conflict.localValue);state.conflicts.add(conflict.address)}for(const [a,v] of Object.entries(local.sheets[0].cells)){if(!e.data.conflicts.some(c=>c.address===a)&&(server.sheets[0].cells[a]??'')!==v)setRawDirect(a,v)}state.dirty=true}updateStatus(e.status===409?'Save rejected: resolve conflicting cells':`Save failed: ${e.message}`);render()}}
async function startSession(userId){if(state.sessionId){state.eventSource?.close();await fetch(`/api/sessions/${state.sessionId}`,{method:'DELETE'}).catch(()=>{})}const data=await request('/api/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId,workbookId:'ops-plan'})});state.user=userId;state.sessionId=data.sessionId;$('current-user').textContent=data.user.name;connectEvents();sendPresence()}
function connectEvents(){state.eventSource?.close();const es=new EventSource(`/api/events?sessionId=${encodeURIComponent(state.sessionId)}`);state.eventSource=es;es.addEventListener('presence',e=>{state.presence=JSON.parse(e.data);renderPresence()});es.addEventListener('revision',e=>handleRemote(JSON.parse(e.data)));es.onerror=()=>{$('presence-summary').textContent='Reconnecting live views…'}}
function handleRemote(event){if(event.userId===state.user&&event.revision===state.revision)return;if(event.revision<=state.revision)return;const draft=new Map();if(state.dirty){for(const [a,v] of Object.entries(sheet().cells)){if((state.saved.sheets[0].cells[a]??'')!==v)draft.set(a,v)}for(const a of Object.keys(state.saved.sheets[0].cells))if(!(a in sheet().cells))draft.set(a,'')}state.saved=clone(event.workbook);state.workbook=clone(event.workbook);state.revision=event.revision;for(const [a,v] of draft){const changedRemotely=(state.saved.sheets[0].cells[a]??'')!==(event.workbook.sheets[0].cells[a]??'');setRawDirect(a,v);if(event.changed?.some(x=>x.address===a))state.conflicts.add(a)}state.dirty=draft.size>0;render();loadRevisions();loadCellHistory()}
async function loadCellHistory(){if(!state.workbook)return;const a=state.selection.end;try{const data=await request(`/api/workbooks/ops-plan/history/plan/${a}`);$('history-address').textContent=a;$('last-changed').textContent=data.lastChangedBy?`Last changed by ${data.lastChangedBy.name} · ${new Date(data.lastChangedBy.changedAt).toLocaleString()}`:'No saved changes to this cell';$('cell-history').innerHTML=data.changes.map(x=>`<li><strong>Revision ${x.revision} · ${escapeHtml(x.name)}</strong><span class="muted">${new Date(x.changedAt).toLocaleString()}</span><br><code>${escapeHtml(x.previousValue||'(blank)')} → ${escapeHtml(x.newValue||'(blank)')}</code></li>`).join('')}catch{}}
async function loadRevisions(){const data=await request('/api/workbooks/ops-plan/revisions');$('revision-history').innerHTML=data.revisions.map(x=>`<li><button data-preview="${x.revision}"><strong>Revision ${x.revision}</strong>${new Date(x.createdAt).toLocaleString()}${x.name?` · ${escapeHtml(x.name)}`:' · Initial seed'}</button><div class="history-actions"><button data-preview="${x.revision}">Preview</button><button data-restore="${x.revision}">Restore as draft</button></div></li>`).join('')}
async function previewRevision(revision){endEdit(false);const data=await request(`/api/workbooks/ops-plan/revisions/${revision}`);if(!state.preview)state.preview={workbook:clone(state.workbook),selection:clone(state.selection)};state.workbook=clone(data.workbook);$('close-preview').hidden=false;$('preview-note').textContent=`Previewing revision ${revision}. Live content and dirty state are unchanged.`;render();updateStatus(`Previewing revision ${revision}`)}
function closePreview(){if(!state.preview)return;state.workbook=state.preview.workbook;state.selection=state.preview.selection;state.preview=null;$('close-preview').hidden=true;$('preview-note').textContent='Preview or restore a saved revision.';render()}
